"""Generate app/src/main/java/app/f2ltrainer/data/CaseData.kt and the test fixture from
cases_src.py (after verification by build_cases.py)."""
import os
from build_cases import build, describe
from f2l import pair_key
from cases_src import GROUPS

ROOT = os.path.join(os.path.dirname(__file__), "..", "app", "src")
out, errors = build()
if errors:
    raise SystemExit("\n".join(errors))

def q(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'

lines = [
    "package app.f2ltrainer.data",
    "",
    "// GENERATED by tools/gen_kotlin.py from tools/cases_src.py - do not edit by hand.",
    "// Every algorithm was verified by the Python cube model and is verified again by the",
    "// unit tests in app/src/test (CaseDataTest).",
    "",
    "internal object CaseData {",
    "    val CASES: List<RawCase> = listOf(",
]
for c in out:
    algs = ", ".join(q(a) for a in c['algs'])
    free = q(c['free']) if c['free'] else "null"
    lines.append("        RawCase(%d, CaseGroup.%s, listOf(%s), %s)," % (c['id'], c['group'].upper(), algs, free))
lines += ["    )", "}", ""]
open(os.path.join(ROOT, "main/java/app/f2ltrainer/data/CaseData.kt"), "w").write("\n".join(lines))

t = [
    "package app.f2ltrainer",
    "",
    "// GENERATED by tools/gen_kotlin.py: expected FR-pair placement of every case's picture",
    "// as computed by the independent Python model. (cornerCrossFacelet, edgeFrontFacelet)",
    "",
    "object ExpectedPairs {",
    "    val BY_ID: Map<Int, Pair<Int, Int>> = mapOf(",
]
for c in out:
    ck, ek = pair_key(c['display'])
    t.append("        %d to (%d to %d), // %s" % (c['id'], ck, ek, describe(c['key'])))
t += ["    )", "}", ""]
open(os.path.join(ROOT, "test/java/app/f2ltrainer/ExpectedPairs.kt"), "w").write("\n".join(t))
print("generated", len(out), "cases")
